mapper.delete:
DELETE FROM OFT_RECIPE_STEP_IMAGE
WHERE STEP_NO IN (
    SELECT STEP_NO
    FROM OFT_RECIPE_STEP
    WHERE RECIPE_NO = #{value}
)

mapper.insert:
INSERT INTO OFT_RECIPE_INGREDIENT (
    RECIPE_NO,
    INGREDIENT_NAME,
    AMOUNT
)
VALUES (
    #{recipeNo},
    #{ingredientName},
    #{amount}
)

INSERT INTO OFT_RECIPE_STEP (
    RECIPE_NO,
    STEP_SEQ,
    DESCRIPTION
)
VALUES (
    #{recipeNo},
    #{stepSeq},
    #{description}
)

    SELECT STEP_NO
    FROM OFT_RECIPE_STEP
    WHERE RECIPE_NO = #{recipeNo}
      AND STEP_SEQ = #{stepSeq}

INSERT INTO OFT_RECIPE_STEP_IMAGE (
    STEP_NO,
    IMAGE_URL,
    SORT_ORDER
)
VALUES (
    #{stepNo},
    #{imageUrl},
    #{sortOrder}
)

mapper.select:
SELECT * FROM ( SELECT RECIPE_NO AS recipeNo, EXTERNAL_RECIPE_ID AS externalRecipeId, RECIPE_NAME AS recipeName, DESCRIPTION AS description, COOK_TIME AS cookTime, DIFFICULTY AS difficulty, CALORIES AS calories, IMAGE_URL AS imageUrl, SOURCE_NAME AS sourceName FROM OFT_RECIPE WHERE 1 = 1
AND UPPER(RECIPE_NAME) LIKE '%' || UPPER(#{keyword}) || '%'
ORDER BY RECIPE_NO DESC ) WHERE ROWNUM <= #{limit}
